package android.net.nsd;import java.net.*;public class NsdServiceInfo {public String type,name="local-adb";public int port=37599;public InetAddress host;public NsdServiceInfo(String type){this.type=type;try{host=InetAddress.getByName("127.0.0.1");}catch(Exception e){throw new RuntimeException(e);}}public String getServiceType(){return type;}public String getServiceName(){return name;}public int getPort(){return port;}public InetAddress getHost(){return host;}}
